  1	/* ============================================================
  2	   views/orchestrator.js — Orchestrator View
  3	   MCP Server Dashboard SPA — Phase 5 (WP-011)
  4	
  5	   Renders the top-level orchestrator view:
  6	     Section A: plan path input + preflight + start
  7	     Section B: live run queue table with polling
  8	     Footer: CLI reference card
  9	
 10	   Depends on: API (api-client.js), Router (router.js),
 11	               OrchestratorWidgets (js/orchestrator-widgets.js),
 12	               escapeHtml (utils.js)
 13	   ============================================================ */
 14	
 15	// Module-scoped log-preview cleanup registry.
 16	// Each renderOrchestrator() call drains this array before creating new widgets.
 17	var _orchLogPreviewCleanups = [];
 18	
 19	/**
 20	 * Top-level orchestrator view entry point.
 21	 * Called by Router.dispatch() when the user navigates to #/orchestrator.
 22	 *
 23	 * @param {HTMLElement} app - The root #app container element.
 24	 */
 25	function renderOrchestrator(app) {
 26	  // 1. Drain log preview cleanup callbacks from the previous render.
 27	  _orchLogPreviewCleanups.forEach(function (fn) { try { fn(); } catch (_) {} });
 28	  _orchLogPreviewCleanups = [];
 29	
 30	  // 2. Render the static skeleton.
 31	  app.innerHTML =
 32	    '<h1 class="section-title">Orchestrator</h1>' +
 33	
 34	    '<section class="orch-section">' +
 35	      '<h2 class="orch-section-title">Start New Run</h2>' +
 36	      '<div class="orch-start-panel">' +
 37	        '<div class="orch-plan-input-row">' +
 38	          '<input type="text" id="orch-plan-path" class="orch-plan-input"' +
 39	            ' placeholder="Absolute path to plan.md…" autocomplete="off">' +
 40	          '<button type="button" id="orch-preflight-btn" class="btn btn-secondary">' +
 41	            'Run Preflight' +
 42	          '</button>' +
 43	          '<button type="button" id="orch-start-btn" class="btn btn-primary" disabled>' +
 44	            'Start Run' +
 45	          '</button>' +
 46	        '</div>' +
 47	        '<div id="orch-preflight-results"></div>' +
 48	      '</div>' +
 49	    '</section>' +
 50	
 51	    '<section class="orch-section">' +
 52	      '<h2 class="orch-section-title">Run Queue</h2>' +
 53	      '<div id="orch-queue-container"><p class="text-muted">Loading queue…</p></div>' +
 54	    '</section>' +
 55	
 56	    '<section class="orch-section orch-cli-section">' +
 57	      OrchestratorWidgets.renderCliReference() +
 58	    '</section>';
 59	
 60	  // 3. Bind UI references.
 61	  var preflightBtn = document.getElementById('orch-preflight-btn');
 62	  var startBtn     = document.getElementById('orch-start-btn');
 63	  var planInput    = document.getElementById('orch-plan-path');
 64	  var resultsEl    = document.getElementById('orch-preflight-results');
 65	
 66	  var allChecksPassed = false;
 67	
 68	  // 4. Render preflight results checklist.
 69	  function renderPreflightResults(checks) {
 70	    if (!checks || !checks.length) {
 71	      resultsEl.innerHTML = '';
 72	      allChecksPassed = false;
 73	      startBtn.disabled = true;
 74	      return;
 75	    }
 76	    allChecksPassed = checks.every(function (c) { return c.pass; });
 77	    startBtn.disabled = !allChecksPassed;
 78	    if (!startBtn.disabled) startBtn.textContent = 'Start Run';
 79	
 80	    var html = '<ul class="preflight-list">';
 81	    checks.forEach(function (c) {
 82	      var cls = c.pass ? 'preflight-pass' : 'preflight-fail';
 83	      html += '<li class="preflight-check ' + cls + '">';
 84	      html += '<span class="preflight-icon">' + (c.pass ? '✓' : '✗') + '</span>';
 85	      html += ' <strong>' + escapeHtml(c.name) + '</strong>: ' + escapeHtml(c.detail);
 86	      if (!c.pass && c.fix) {
 87	        html += ' <span class="preflight-fix">Fix: <code>' + escapeHtml(c.fix) + '</code></span>';
 88	      }
 89	      html += '</li>';
 90	    });
 91	    html += '</ul>';
 92	    resultsEl.innerHTML = html;
 93	  }
 94	
 95	  // 5. Preflight button handler.
 96	  preflightBtn.addEventListener('click', function () {
 97	    var planPath = planInput.value.trim();
 98	    if (!planPath) { window.alert('Please enter a plan path.'); return; }
 99	
100	    preflightBtn.disabled = true;

101	    preflightBtn.textContent = 'Running…';
102	    resultsEl.innerHTML = '<p class="text-muted">Running preflight checks…</p>';
103	    allChecksPassed = false;
104	    startBtn.disabled = true;
105	
106	    API.orchestratorStart(planPath, true).then(function (result) {
107	      renderPreflightResults((result && result.checks) ? result.checks : []);
108	    }).catch(function (err) {
109	      resultsEl.innerHTML = '<p class="error-banner">Preflight error: ' +
110	        escapeHtml((err && err.message) ? err.message : String(err)) + '</p>';
111	    }).then(function () {
112	      preflightBtn.disabled = false;
113	      preflightBtn.textContent = 'Run Preflight';
114	    });
115	  });
116	
117	  // 6. Start Run button handler.
118	  startBtn.addEventListener('click', function () {
119	    var planPath = planInput.value.trim();
120	    if (!planPath || !allChecksPassed) return;
121	
122	    startBtn.disabled = true;
123	    startBtn.textContent = 'Starting…';
124	
125	    API.orchestratorStart(planPath, false).then(function (result) {
126	      if (result && result.started) {
127	        var runStatusFilename = result.runStatusFilename || null;
128	        planInput.value = '';
129	        resultsEl.innerHTML =
130	          '<p class="success-banner">✓ Orchestrator launched' +
131	          (result.pid ? ' (PID\u00a0' + result.pid + ')' : '') +
132	          '. Waiting for the run to appear in the queue below…</p>';
133	        allChecksPassed = false;
134	        startBtn.disabled = true;
135	        refreshQueue();
136	
137	        // Poll the run-status tombstone so we can surface fatal early
138	        // failures (e.g. invalid API key) that complete before the first
139	        // queue poll cycle.
140	        if (runStatusFilename) {
141	          var pollCount = 0;
142	          var MAX_STATUS_POLLS = 15; // 2s × 15 = 30s window
143	          var statusPollTimer = setInterval(function () {
144	            pollCount++;
145	            API.orchestratorGetRunStatus(runStatusFilename).then(function (status) {
146	              if (!status) return; // file not yet written — run still in progress
147	              clearInterval(statusPollTimer);
148	              if (status.result === 'ERROR' && status.error) {
149	                resultsEl.innerHTML =
150	                  '<p class="error-banner">Run failed: ' +
151	                  escapeHtml(status.error) + '</p>';
152	              }
153	              // SUCCESS: queue will reflect the project; leave the banner.
154	            }).catch(function () {
155	              // Transient error — keep polling.
156	            });
157	            if (pollCount >= MAX_STATUS_POLLS) {
158	              clearInterval(statusPollTimer);
159	            }
160	          }, 2000);
161	        }
162	      } else {
163	        // Checks re-evaluated by server — update the checklist.
164	        renderPreflightResults((result && result.checks) ? result.checks : []);
165	      }
166	    }).catch(function (err) {
167	      window.alert('Failed to start: ' + ((err && err.message) ? err.message : String(err)));
168	      startBtn.disabled = !allChecksPassed;
169	      startBtn.textContent = 'Start Run';
170	    }).then(function () {
171	      startBtn.textContent = 'Start Run';
172	    });
173	  });
174	
175	  // 7. Queue refresh and rendering — tracks expanded row IDs across refreshes.
176	  var expandedIds = {};
177	
178	  function refreshQueue() {
179	    // Stop log preview intervals started in the previous queue render.
180	    _orchLogPreviewCleanups.forEach(function (fn) { try { fn(); } catch (_) {} });
181	    _orchLogPreviewCleanups = [];
182	
183	    var container = document.getElementById('orch-queue-container');
184	    if (!container) return;
185	
186	    API.orchestratorGetQueue().then(function (entries) {
187	      renderQueueTable(container, Array.isArray(entries) ? entries : []);
188	    }).catch(function () {
189	      // Best-effort polling — keep existing content on transient errors.
190	    });
191	  }
192	
193	  function renderQueueTable(container, entries) {
194	    if (!entries.length) {
195	      container.innerHTML = '<p class="text-muted orch-empty-queue">No active runs in the queue.</p>';
196	      return;
197	    }
198	
199	    // Clear the launch success banner once the queue has at least one entry.
200	    // Only the success banner is removed — error banners are intentionally left intact.
201	    var successBanner = resultsEl.querySelector('.success-banner');
202	    if (successBanner) {
203	      successBanner.remove();
204	    }
205	
206	    var html = '<table class="table orch-queue-table"><thead>' +
207	      '<tr><th></th><th>Plan</th><th>Status</th><th>Elapsed</th><th>Progress</th><th>Actions</th></tr>' +
208	      '</thead><tbody>';
209	
210	    entries.forEach(function (entry) {
211	      var id       = entry.id || '';
212	      var status   = entry.effectiveStatus || 'pending';
213	      var planName = _orchBasename(entry.planPath || '');
214	      var elapsed  = _orchElapsed(entry.startedAt);
215	      var isExpanded = !!expandedIds[id];
216	
217	      var statusBadgeHtml =
218	        '<span class="badge badge-' + escapeHtml(status) + '">' +
219	        escapeHtml(_orchStatusLabel(status)) + '</span>';
220	
221	      // Progress cell: badge + text summary + optional log link.
222	      var progressHtml = OrchestratorWidgets.renderProgressBadge(entry.lastAction || null);
223	      if (entry.progress) {
224	        progressHtml += ' <span class="orch-progress-text">' + escapeHtml(entry.progress) + '</span>';
225	      }
226	      if (entry.logFilename && entry.expectedSlug) {
227	        progressHtml += ' <a href="#/projects/' +
228	          encodeURIComponent(entry.expectedSlug) + '/runs/' +
229	          encodeURIComponent(entry.logFilename) + '" class="orch-log-link">View Log →</a>';
230	      } else if (!entry.progress) {
231	        progressHtml += ' <span class="text-muted">Waiting for log…</span>';
232	      }
233	
234	      html += '<tr class="orch-queue-row orch-row-' + escapeHtml(status) + '"' +
235	        ' data-entry-id="' + escapeHtml(id) + '">';
236	
237	      html += '<td class="orch-toggle-cell">' +
238	        '<button type="button" class="orch-row-toggle btn-icon" data-entry-id="' + escapeHtml(id) + '">' +
239	        (isExpanded ? '▼' : '▶') + '</button></td>';
240	
241	      html += '<td class="orch-plan-cell" title="' + escapeHtml(entry.planPath || '') + '">' +
242	        escapeHtml(planName) + '</td>';
243	
244	      html += '<td class="orch-status-cell">' + statusBadgeHtml + '</td>';
245	      html += '<td class="orch-elapsed-cell">' + escapeHtml(elapsed) + '</td>';
246	      html += '<td class="orch-progress-cell">' + progressHtml + '</td>';
247	      html += '<td class="orch-actions-cell" data-actions-for="' + escapeHtml(id) + '"></td>';
248	      html += '</tr>';
249	
250	      if (isExpanded) {

251	        html += '<tr class="orch-log-row" data-entry-id="' + escapeHtml(id) + '">' +
252	          '<td colspan="6">' +
253	          '<div class="orch-log-preview" id="orch-log-' + escapeHtml(id) + '"></div>' +
254	          '</td></tr>';
255	      }
256	    });
257	
258	    html += '</tbody></table>';
259	    container.innerHTML = html;
260	
261	    // Inject DOM-based action buttons (can't be serialised to HTML strings).
262	    entries.forEach(function (entry) {
263	      var id     = entry.id || '';
264	      var status = entry.effectiveStatus || 'pending';
265	      var cell   = container.querySelector('[data-actions-for="' + id + '"]');
266	      if (!cell) return;
267	
268	      if (status === 'pending') {
269	        cell.appendChild(OrchestratorWidgets.renderKillButton(id, function () {
270	          delete expandedIds[id];
271	          refreshQueue();
272	        }));
273	      } else if (status === 'started' && entry.expectedSlug) {
274	        var link = document.createElement('a');
275	        link.href = '#/projects/' + encodeURIComponent(entry.expectedSlug);
276	        link.className = 'btn btn-sm btn-secondary orch-project-link';
277	        link.textContent = 'View Project';
278	        cell.appendChild(link);
279	      } else if (status === 'dead') {
280	        cell.appendChild(OrchestratorWidgets.renderDismissButton(id, function () {
281	          delete expandedIds[id];
282	          refreshQueue();
283	        }));
284	      }
285	    });
286	
287	    // Start log previews for expanded rows.
288	    entries.forEach(function (entry) {
289	      var id = entry.id || '';
290	      if (!expandedIds[id] || !entry.logFilename || !entry.expectedSlug) return;
291	      var previewEl = document.getElementById('orch-log-' + id);
292	      if (!previewEl) return;
293	      var cleanup = OrchestratorWidgets.renderLogPreview(
294	        previewEl,
295	        entry.expectedSlug,
296	        entry.logFilename,
297	      );
298	      _orchLogPreviewCleanups.push(cleanup);
299	    });
300	
301	    // Attach expand/collapse toggle listeners.
302	    var toggleBtns = container.querySelectorAll('.orch-row-toggle');
303	    Array.prototype.forEach.call(toggleBtns, function (btn) {
304	      btn.addEventListener('click', function () {
305	        var id = btn.getAttribute('data-entry-id');
306	        if (id) expandedIds[id] = !expandedIds[id];
307	        refreshQueue();
308	      });
309	    });
310	  }
311	
312	  // 8. Kick off the first queue fetch and register the polling interval.
313	  refreshQueue();
314	  Router._setPolling(refreshQueue, 5000);
315	}
316	
317	// ---------------------------------------------------------------------------
318	// Private helpers
319	// ---------------------------------------------------------------------------
320	
321	/** Returns the final path segment (filename or folder name). */
322	function _orchBasename(path) {
323	  var parts = String(path).replace(/\\/g, '/').split('/');
324	  return parts[parts.length - 1] || path;
325	}
326	
327	/** Human-readable label for an effectiveStatus value. */
328	function _orchStatusLabel(status) {
329	  if (status === 'started') return 'Started';
330	  if (status === 'dead')    return 'Dead';
331	  return 'Pending';
332	}
333	
334	/** Formats elapsed time from an ISO start timestamp. */
335	function _orchElapsed(startedAt) {
336	  if (!startedAt) return '—';
337	  try {
338	    var diff = Date.now() - new Date(startedAt).getTime();
339	    if (isNaN(diff) || diff < 0) return '—';
340	    var secs = Math.round(diff / 1000);
341	    if (secs < 60)  return secs + 's';
342	    var mins = Math.floor(secs / 60);
343	    if (mins < 60)  return mins + 'm ' + (secs % 60) + 's';
344	    return Math.floor(mins / 60) + 'h ' + (mins % 60) + 'm';
345	  } catch (_) {
346	    return '—';
347	  }
348	}

